module TopModule(
   input   clk,
   input   rst_n,

   output  reg [3:0] gray_out
);
//Gray code to binary conversion
reg  [3:0] bin_out;
wire [3:0] gray_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_out <= 4'b0;
   end
   else begin
      bin_out[3] = gray_wire[3];
      bin_out[2] = gray_wire[2]^gray_wire[1];
      bin_out[1] = gray_wire[1]^bin_out[2];
      bin_out[0] = gray_wire[0]^bin_out[1];
   end 
end
//Binary increment
reg [3:0] bin_add_wire;
always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_add_wire <= 4'b0;
   end
   else begin
      bin_add_wire <= bin_out + 1'b1;
   end
end
//Binary to gray code conversion
assign gray_wire = (bin_add_wire >> 3) ^ bin_add_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      gray_out <= 4'b0;
   end
   else begin
      gray_out <= gray_wire;
   end
end
endmodule","editable":true}},"lens_instruction":"You repair a functional RTL bug in a repository using the specification, the visible directed test and its results. Only the files marked editable may change.","output_constraints":{"additional_keys_allowed":false,"full_source_only":true,"required_files":["rtl/sequence.sv"],"required_top_level_keys":["files","edit"]},"previous_attempts":[],"public_repair_guidance":"Analyze the public Gray-counter specification together with the visible testbench. Internally trace the first eight rising edges after reset: old/new binary decode, increment register, Gray wire and output. A multi-register feedback implementation may already produce the required two-clock cadence; do not add a toggle/enable simply because the specification says every two cycles. Check output phase against public expected values before altering correct registers or latency. Gray-to-binary decoding has dependencies between bits: blindly replacing chained blocking assignments with nonblocking assignments makes later bits read old register values. Evaluate dependent expressions from the intended same-cycle inputs. Prefer the smallest repair supported by public evidence, then recheck all bits, wraparound, asynchronous reset and output hold. On correction, address the actual public failing cycle instead of repeating a generic rewrite. Return only complete files/edit JSON; do not output your internal trace.","repair_experience":{"entries":[{"content":{"applied_patch":"--- a/rtl/sequence.sv
